def is_Sum_Of_Powers_Of_Two(n):
    """Write a python function to check whether the given number can be represented as sum of non-zero powers of 2 or not."""
    # The binary expansion of a positive integer expresses it as a sum of
    # distinct powers of two. That expansion uses only non-zero powers
    # (2, 4, 8, ...) exactly when it does not need 2**0 == 1, i.e. when
    # the number is even. Non-positive numbers cannot be such a sum.
    if n <= 0:
        return False
    return n % 2 == 0
